2	package org.springframework.samples.petclinic.rest.function.owner;
3	
4	import net.officefloor.plugin.section.clazz.Flow;
5	import net.officefloor.server.http.HttpHeader;
6	import net.officefloor.server.http.ServerHttpConnection;
7	import net.officefloor.web.ObjectResponse;
8	import org.springframework.samples.petclinic.mapper.OwnerMapper;
9	import org.springframework.samples.petclinic.model.Owner;
10	import org.springframework.samples.petclinic.repository.OwnerRepository;
11	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
12	
13	/**
14	 * First step of {@code POST /api/owners}. Honours an optional {@code Idempotency-Key} header: when
15	 * the request repeats a key already recorded by {@link RecordIdempotency}, the originally created
16	 * owner is returned with 200 and the create pipeline is short-circuited, so no duplicate is created
17	 * (and the usual identity-conflict 409 is never reached). Otherwise — no key, or a key not seen
18	 * before — the {@code create} flow is taken to run the normal validate/build/save pipeline.
19	 */
20	public class CheckIdempotency {
21	
22	    /** Header naming the idempotency key; absent means a normal (non-idempotent) create. */
23	    static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
24	
25	    @FunctionalInterface
26	    public interface CreateFlow {
27	        void create();
28	    }
29	
30	    public void service(ServerHttpConnection connection, IdempotencyStore idempotencyStore,
31	            OwnerRepository ownerRepository, OwnerMapper ownerMapper, ObjectResponse<OwnerDto> response,
32	            @Flow("create") CreateFlow createFlow) {
33	        String key = idempotencyKey(connection);
34	        if (key != null) {
35	            Integer existingId = idempotencyStore.get(key);
36	            if (existingId != null) {
37	                Owner existing = ownerRepository.findById(existingId);
38	                if (existing != null) {
39	                    response.send(ownerMapper.toOwnerDto(existing)); // 200, no duplicate created
40	                    return; // short-circuit: do not take the create flow
41	                }
42	            }
43	        }
44	        createFlow.create();
45	    }
46	
47	    /** The trimmed {@code Idempotency-Key} header value, or {@code null} when absent or blank. */
48	    static String idempotencyKey(ServerHttpConnection connection) {
49	        HttpHeader header = connection.getRequest().getHeaders().getHeader(IDEMPOTENCY_KEY_HEADER);
50	        if (header == null) {
51	            return null;
52	        }
53	        String value = header.getValue();
54	        if (value == null || value.isBlank()) {
55	            return null;
56	        }
57	        return value.trim();
58	    }
59	}
