62	package org.springframework.samples.petclinic.rest.function.owner;
63	
64	import java.time.LocalDate;
65	import java.util.ArrayList;
66	import java.util.List;
67	
68	import net.officefloor.plugin.variable.Out;
69	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
70	import org.springframework.samples.petclinic.rest.escalation.OwnerEmailDisposableException;
71	import org.springframework.samples.petclinic.rest.escalation.OwnerEmailInvalidException;
72	import org.springframework.samples.petclinic.rest.escalation.OwnerFieldsRequiredException;
73	import org.springframework.samples.petclinic.rest.escalation.OwnerPostcodeInvalidException;
74	import org.springframework.samples.petclinic.rest.escalation.OwnerRegistrationDateFutureException;
75	import org.springframework.samples.petclinic.rest.escalation.OwnerTelephoneInvalidException;
76	import org.springframework.web.bind.annotation.RequestBody;
77	
78	/**
79	 * First step of {@code POST /api/owners}. Rejects a request that is missing or blank in any of
80	 * firstName, lastName, address, city or telephone, collecting every offending field name so the
81	 * response can list them all. The address may be given in structured form (addressLine1 [+
82	 * addressLine2]) or via the legacy flat 'address' field; it is composed and normalized first (see
83	 * {@link OwnerAddress#compose(String, String, String)}) and rejected when neither form yields a
84	 * non-blank value. It then normalizes the telephone into E.164 form (see
85	 * {@link OwnerTelephone#toE164(String)}), storing the normalized address lines, composed address and
86	 * telephone back on the body so they are persisted and
87	 * returned. On success it publishes the body for {@link BuildOwner} to consume
88	 * (only one step may bind {@code @RequestBody}).
89	 */
90	public class ValidateOwnerFields {
91	
92	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
93	            throws OwnerFieldsRequiredException, OwnerTelephoneInvalidException, OwnerEmailInvalidException,
94	            OwnerEmailDisposableException, OwnerPostcodeInvalidException, OwnerRegistrationDateFutureException {
95	        // A supplied registration date cannot be in the future — reject one later than today.
96	        LocalDate registrationDate = request.getRegistrationDate();
97	        LocalDate serverDate = LocalDate.now();
98	        if (registrationDate != null && registrationDate.isAfter(serverDate)) {
99	            throw new OwnerRegistrationDateFutureException(registrationDate, serverDate);
100	        }
101	        List<String> errors = new ArrayList<>();
102	        require("firstName", request.getFirstName(), errors);
103	        require("lastName", request.getLastName(), errors);
104	        // An address may be supplied in structured form (addressLine1 [+ addressLine2]) or via the
105	        // legacy flat 'address' field; the structured form is preferred when present. Normalize each
106	        // supplied part up front so the required check rejects one that is blank after normalization
107	        // and the normalized values are what get stored and returned.
108	        String normalizedLine1 = OwnerAddress.normalize(request.getAddressLine1());
109	        String normalizedLine2 = OwnerAddress.normalize(request.getAddressLine2());
110	        String composedAddress =
111	                OwnerAddress.compose(request.getAddressLine1(), request.getAddressLine2(), request.getAddress());
112	        if (composedAddress == null) {
113	            errors.add("address");
114	        }
115	        require("city", request.getCity(), errors);
116	        require("telephone", request.getTelephone(), errors);
117	        if (!errors.isEmpty()) {
118	            throw new OwnerFieldsRequiredException(errors);
119	        }
120	        // Postcode is optional; when present it must be 4 digits and valid for the city's region.
121	        OwnerPostcode.validate(request.getPostcode(), request.getCity());
122	        request.setAddressLine1(normalizedLine1);
123	        request.setAddressLine2(normalizedLine2);
124	        request.setAddress(composedAddress);
125	        request.setTelephone(OwnerTelephone.toE164(request.getTelephone()));
126	        request.setEmail(OwnerEmail.normalize(request.getEmail()));
127	        validated.set(request);
128	    }
129	
130	    private static void require(String field, String value, List<String> errors) {
131	        if (value == null || value.isBlank()) {
132	            errors.add(field);
133	        }
134	    }
135	}
