138	package org.springframework.samples.petclinic.rest.function.owner;
139	
140	import java.time.LocalDate;
141	
142	import net.officefloor.plugin.variable.Val;
143	import org.springframework.samples.petclinic.model.Owner;
144	import org.springframework.samples.petclinic.repository.OwnerRepository;
145	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
146	import org.springframework.samples.petclinic.rest.escalation.OwnerDailyLimitException;
147	
148	/**
149	 * Rejects a create-owner request once the daily sign-up limit is reached — 100 or more owners have
150	 * already been created for the request's business day, counted by
151	 * {@link Owner#getRegistrationDate() registrationDate} equal to the effective registration date.
152	 * That effective date is the one supplied in the request (or the server's current date when
153	 * omitted), rolled forward to the next business day (see
154	 * {@link RegistrationDates#toBusinessDay(LocalDate)}) exactly as {@link BuildOwner} stores it, so
155	 * the limit counts owners per adjusted business day. Throws {@link OwnerDailyLimitException}
156	 * (handled as 429) when the limit is met or exceeded.
157	 */
158	public class CheckOwnerDailyLimit {
159	
160	    /** The maximum number of owners permitted to be created on a single day. */
161	    private static final int DAILY_LIMIT = 100;
162	
163	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
164	            throws OwnerDailyLimitException {
165	        LocalDate supplied = request.getRegistrationDate();
166	        LocalDate businessDay = RegistrationDates.toBusinessDay(supplied != null ? supplied : LocalDate.now());
167	        int count = 0;
168	        for (Owner existing : ownerRepository.findAll()) {
169	            if (businessDay.equals(existing.getRegistrationDate())) {
170	                count++;
171	            }
172	        }
173	        if (count >= DAILY_LIMIT) {
174	            throw new OwnerDailyLimitException(businessDay, count);
175	        }
176	    }
177	}
