188	/**
189	 * Rejects a create-owner request whose city has reached capacity — it already contains 50 or more
190	 * owners (compared case-insensitively). Throws {@link OwnerCityCapacityException} (handled as 409)
191	 * when the limit is met or exceeded.
192	 */
193	public class CheckOwnerCityCapacity {
194	
195	    /** The maximum number of owners permitted in a single city. */
196	    private static final int CITY_CAPACITY = 50;
197	
198	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
199	            throws OwnerCityCapacityException {
200	        String city = request.getCity();
201	        int count = 0;
202	        for (Owner existing : ownerRepository.findAll()) {
203	            if (city == null ? existing.getCity() == null : city.equalsIgnoreCase(existing.getCity())) {
204	                count++;
205	            }
206	        }
207	        if (count >= CITY_CAPACITY) {
208	            throw new OwnerCityCapacityException(city, count);
209	        }
210	    }
211	}
