224	/**
225	 * Builds the {@link Owner} entity from the request body already validated and published by
226	 * {@link ValidateOwnerFields} (the body can be bound with {@code @RequestBody} only once).
227	 * When the request omits a registration date, it defaults to the server's current date. The
228	 * effective registration date is then rolled forward to the next business day (see
229	 * {@link RegistrationDates#toBusinessDay(LocalDate)}), so a weekend date — supplied or defaulted —
230	 * lands on a Monday and every value derived from it uses the adjusted date.
231	 */
232	public class BuildOwner {
233	
234	    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built) {
235	        Owner owner = ownerMapper.toOwner(request);
236	        LocalDate registrationDate = owner.getRegistrationDate();
237	        if (registrationDate == null) {
238	            registrationDate = LocalDate.now();
239	        }
240	        owner.setRegistrationDate(RegistrationDates.toBusinessDay(registrationDate));
241	        built.set(owner);
242	    }
243	}
