246	package org.springframework.samples.petclinic.rest.function.owner;
247	
248	import java.nio.charset.StandardCharsets;
249	import java.security.MessageDigest;
250	
251	import net.officefloor.plugin.variable.Val;
252	import org.springframework.samples.petclinic.model.Owner;
253	
254	/**
255	 * Assigns the owner's deterministic {@code householdId}: the first 12 hex characters of SHA-256 over
256	 * the normalized lastName, a {@code '|'} separator and the postcode. The household is therefore
257	 * keyed on {@code (lastName, postcode)} alone — owners with the same lastName (compared
258	 * case-insensitively with collapsed whitespace) and the same postcode receive the same id
259	 * automatically, regardless of creation order and without inspecting or updating any other owner.
260	 *
261	 * <p>The {@code sharesHousehold} request flag no longer creates the link — the id is always computed
262	 * here — it only bypasses the household duplicate block in {@link CheckOwnerIdentityUnique}.
263	 * Everything that keys off the household ({@link CheckOwnerIdentityUnique} duplicate detection and
264	 * the {@link AssignHouseholdSize} household size) reads this computed id.
265	 *
266	 * <p>Runs after {@link BuildOwner} (the entity exists) and before those steps.
267	 */
268	public class AssignHousehold {
269	
270	    public void service(@Val Owner owner) {
271	        String lastName = normalize(owner.getLastName());
272	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
273	        owner.setHouseholdId(deriveHouseholdId(lastName, postcode));
274	    }
275	
276	    /** Lower-cased, trimmed, with internal whitespace runs collapsed to a single space. */
277	    private static String normalize(String value) {
278	        if (value == null) {
279	            return "";
280	        }
281	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
282	    }
283	
284	    /** The first 12 hex characters of SHA-256(normalizedLastName {@code '|'} postcode), so it is
285	     *  identical for every owner sharing that lastName and postcode. */
286	    private static String deriveHouseholdId(String normalizedLastName, String postcode) {
287	        try {
288	            byte[] digest = MessageDigest.getInstance("SHA-256")
289	                    .digest((normalizedLastName + "|" + postcode).getBytes(StandardCharsets.UTF_8));
290	            StringBuilder sb = new StringBuilder(12);
291	            for (int i = 0; i < 6; i++) {
292	                sb.append(String.format("%02x", digest[i]));
293	            }
294	            return sb.toString();
295	        }
296	        catch (Exception ex) {
297	            throw new IllegalStateException("SHA-256 unavailable", ex);
298	        }
299	    }
300	}
