302	======== CheckOwnerIdentityUnique.java ========
303	package org.springframework.samples.petclinic.rest.function.owner;
304	
305	import net.officefloor.plugin.variable.Val;
306	import org.springframework.samples.petclinic.model.Owner;
307	import org.springframework.samples.petclinic.repository.OwnerRepository;
308	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
309	import org.springframework.samples.petclinic.rest.escalation.OwnerIdentityConflictException;
310	
311	/**
312	 * Household duplicate check for {@code POST /api/owners}. The household is keyed on
313	 * {@code (lastName, postcode)} via the deterministic {@code householdId} computed by
314	 * {@link AssignHousehold}, so any existing owner sharing the new owner's {@code householdId} is a
315	 * member of the same household. A second such owner is rejected with 409
316	 * ({@link OwnerIdentityConflictException}).
317	 *
318	 * <p>The {@code sharesHousehold} request flag bypasses this block: when set, the new owner is
319	 * created as a <em>declared</em> household member rather than rejected (and is not flagged a possible
320	 * duplicate — see {@link AssignPossibleDuplicate}). Runs after {@link AssignHousehold} (so the new
321	 * owner already carries its {@code householdId}) and before {@link SaveOwner} (so the new owner is
322	 * not yet in the repository scan).
323	 */
324	public class CheckOwnerIdentityUnique {
325	
326	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository)
327	            throws OwnerIdentityConflictException {
328	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
329	            return; // declared household member: bypass the duplicate block
330	        }
331	        String householdId = owner.getHouseholdId();
332	        for (Owner existing : ownerRepository.findAll()) {
333	            if (Boolean.TRUE.equals(existing.getDeleted())) {
334	                continue; // a soft-deleted owner never blocks a create
335	            }
336	            if (householdId.equals(existing.getHouseholdId())) {
337	                throw new OwnerIdentityConflictException(householdId);
338	            }
339	        }
340	    }
341	}
