343	======== AssignPossibleDuplicate.java ========
344	package org.springframework.samples.petclinic.rest.function.owner;
345	
346	import net.officefloor.plugin.variable.Val;
347	import org.springframework.samples.petclinic.model.Owner;
348	import org.springframework.samples.petclinic.repository.OwnerRepository;
349	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
350	
351	/**
352	 * Flags a soft (possible) duplicate. The new owner is not a household duplicate — an existing owner
353	 * sharing its {@code householdId} would already have been rejected with 409 by
354	 * {@link CheckOwnerIdentityUnique}, unless the request declared {@code sharesHousehold} — but it may
355	 * still be a <em>likely</em> duplicate of an existing owner: same {@code lastName} (compared
356	 * case-insensitively) and same {@code postcode}, yet a different {@code telephone}.
357	 *
358	 * <p>A <em>declared</em> household member ({@code sharesHousehold = true}) is never a suspected
359	 * duplicate: it opted in explicitly, so it is left with {@code possibleDuplicate = false}. Otherwise,
360	 * when a matching existing owner is found, the new owner is still created but carries
361	 * {@code possibleDuplicate = true} and {@code possibleDuplicateOf} set to that existing owner's id;
362	 * when several match, the earliest (lowest id) is used for a deterministic result. Otherwise
363	 * {@code possibleDuplicate = false} and {@code possibleDuplicateOf} is left {@code null}.
364	 *
365	 * <p>Runs after {@link CheckOwnerIdentityUnique} (household duplicates already rejected) and before
366	 * {@link SaveOwner}, so the scan sees only the owners already persisted, not the new owner itself.
367	 */
368	public class AssignPossibleDuplicate {
369	
370	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
371	        owner.setPossibleDuplicate(false);
372	        owner.setPossibleDuplicateOf(null);
373	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
374	            return; // a declared household member is not a suspected duplicate
375	        }
376	        String lastName = owner.getLastName();
377	        String postcode = owner.getPostcode();
378	        String telephone = owner.getTelephone();
379	        if (postcode == null) {
380	            return; // no postcode to match on -> never a possible duplicate
381	        }
382	        Owner match = null;
383	        for (Owner existing : ownerRepository.findAll()) {
384	            if (Boolean.TRUE.equals(existing.getDeleted())) {
385	                continue; // a soft-deleted owner is not a possible duplicate
386	            }
387	            if (!equalsIgnoreCase(lastName, existing.getLastName())) {
388	                continue;
389	            }
390	            if (!postcode.equals(existing.getPostcode())) {
391	                continue;
392	            }
393	            if (equals(telephone, existing.getTelephone())) {
394	                continue; // same telephone is not a soft match (a hard match was already rejected)
395	            }
396	            if (match == null || lowerId(existing.getId(), match.getId())) {
397	                match = existing;
398	            }
399	        }
400	        if (match != null) {
401	            owner.setPossibleDuplicate(true);
402	            owner.setPossibleDuplicateOf(match.getId());
403	        }
404	    }
405	
406	    private static boolean lowerId(Integer candidate, Integer current) {
407	        if (candidate == null) {
408	            return false;
409	        }
410	        return current == null || candidate < current;
411	    }
412	
413	    private static boolean equalsIgnoreCase(String a, String b) {
414	        return a == null ? b == null : a.equalsIgnoreCase(b);
415	    }
416	
417	    private static boolean equals(String a, String b) {
418	        return a == null ? b == null : a.equals(b);
419	    }
420	}
