423	package org.springframework.samples.petclinic.rest.function.owner;
424	
425	import net.officefloor.plugin.variable.Val;
426	import org.springframework.samples.petclinic.model.Owner;
427	import org.springframework.samples.petclinic.repository.OwnerRepository;
428	
429	/**
430	 * Assigns the owner's {@code householdMemberCount}: the number of owners in the new owner's
431	 * household <em>after</em> this create, i.e. the existing members sharing its {@code householdId}
432	 * plus the new owner itself.
433	 *
434	 * <p>Runs after {@link AssignHousehold} (which computes the deterministic {@code householdId} from
435	 * the owner's lastName and postcode) and before {@link SaveOwner}, so the existing members are
436	 * already carrying the same id but the new owner is not yet persisted — hence the {@code + 1}. When
437	 * no existing owner shares the id, the new owner is the sole member and the count is {@code 1}.
438	 *
439	 * <p>The count is persisted on the owner as {@code householdMemberCount} for reporting; it no
440	 * longer influences the membership level (see
441	 * {@link org.springframework.samples.petclinic.model.MembershipLevel}).
442	 */
443	public class AssignHouseholdSize {
444	
445	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
446	        String householdId = owner.getHouseholdId();
447	        int count = 1;
448	        if (householdId != null) {
449	            for (Owner existing : ownerRepository.findAll()) {
450	                if (householdId.equals(existing.getHouseholdId())) {
451	                    count++;
452	                }
453	            }
454	        }
455	        owner.setHouseholdMemberCount(count);
456	    }
457	}
