459	======== AssignCustomerCode.java ========
460	package org.springframework.samples.petclinic.rest.function.owner;
461	
462	import java.nio.charset.StandardCharsets;
463	import java.security.MessageDigest;
464	import java.util.HashSet;
465	import java.util.Map;
466	import java.util.Set;
467	
468	import net.officefloor.plugin.variable.Val;
469	import org.springframework.samples.petclinic.model.Owner;
470	import org.springframework.samples.petclinic.repository.OwnerRepository;
471	
472	/**
473	 * Assigns the owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>} where REGION is the
474	 * region code derived from the owner's postcode (its inclusive range: {@code NSW 2000-2099},
475	 * {@code VIC 3000-3099}, {@code QLD 4000-4099}, else {@code UNKNOWN}) and HASH8 is the first 8
476	 * upper-case hex characters of {@code SHA-256} over the owner's normalized telephone concatenated
477	 * with its last name (e.g. {@code NSW-1A2B3C4D}).
478	 *
479	 * <p>The identity is derived deterministically from the owner's own fields — no sequence numbers —
480	 * so it does not depend on other owners or on creation order. The telephone has already been
481	 * normalized to E.164 form by {@link ValidateOwnerFields} before this step runs.
482	 *
483	 * <p>Should the deterministic code collide with an existing owner's {@code customerCode}, it is
484	 * de-duplicated by appending {@code -<n>} with the smallest {@code n} of 2 or more that makes it
485	 * unique (e.g. {@code NSW-1A2B3C4D}, then {@code NSW-1A2B3C4D-2}, {@code NSW-1A2B3C4D-3}, …).
486	 */
487	public class AssignCustomerCode {
488	
489	    /** Region -&gt; inclusive 4-digit postcode range {@code {low, high}}. */
490	    private static final Map<String, int[]> REGION_RANGE = Map.of(
491	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
492	
493	    private static final String UNKNOWN = "UNKNOWN";
494	
495	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
496	        String region = regionOf(owner.getPostcode());
497	        String hash8 = hash8(owner.getTelephone() + owner.getLastName());
498	        String base = region + "-" + hash8;
499	
500	        Set<String> taken = new HashSet<>();
501	        for (Owner existing : ownerRepository.findAll()) {
502	            if (existing.getCustomerCode() != null) {
503	                taken.add(existing.getCustomerCode());
504	            }
505	        }
506	
507	        String code = base;
508	        for (int n = 2; taken.contains(code); n++) {
509	            code = base + "-" + n;
510	        }
511	        owner.setCustomerCode(code);
512	    }
513	
514	    /** The region whose inclusive range contains {@code postcode}, or {@code UNKNOWN} when the
515	     *  postcode is absent, not four digits, or in no known range. */
516	    private static String regionOf(String postcode) {
517	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
518	            return UNKNOWN;
519	        }
520	        int value = Integer.parseInt(postcode);
521	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
522	            int[] range = entry.getValue();
523	            if (value >= range[0] && value <= range[1]) {
524	                return entry.getKey();
525	            }
526	        }
527	        return UNKNOWN;
528	    }
529	
530	    /** The first 8 upper-case hex characters (4 bytes) of {@code SHA-256(value)}. */
531	    private static String hash8(String value) {
532	        try {
533	            byte[] digest = MessageDigest.getInstance("SHA-256")
534	                    .digest(value.getBytes(StandardCharsets.UTF_8));
535	            StringBuilder sb = new StringBuilder(8);
536	            for (int i = 0; i < 4; i++) {
537	                sb.append(String.format("%02X", digest[i]));
538	            }
